const combineState = reducers => {
  const globalState = {};

  // set default state returned by reducer and its reducer
  for (const [key, value] of Object.entries(reducers)) {

    if (typeof value === "function") {
      globalState[key] = value(undefined, { type: "rubbish" });
    } else {
      console.error(`${value} is not a function`);
    }
  }
  // return the initial state and the global reducer
  return [globalState];
};


/*export const combineReducers = (...reducers: Function[]) => 
  (state: any = initialState, action: any): any => {
    for(let i=0;i<reducers.length;i++) 
      state = reducers[i](state, action)
    return state;
  }*/
  
  
const reduceReducers = (...reducers) => (prevState, value, ...args) =>
  reducers.reduce(
    (newState, reducer) => reducer(newState, value, ...args),
    prevState
  );
  
  
  function reducerA(state, action) {
  switch (action.type) {
    case "increment":
      return { ...state, count: state.count + 1 };
    case "decrement":
      return { ...state, count: state.count - 1 };
    default:
      return state;
  }
}

function reducerB(state, action) {
  switch (action.type) {
    case "double":
      return { ...state, count: state.count * 2 };
    case "halve":
      return { ...state, count: state.count / 2 };
    default:
      return state;
  }
}

export default reduceReducers(reducerA, reducerB);
